const root=document.querySelector('#app');
const pref=(k,fallback)=>{try{return localStorage.getItem('twin-'+k)||fallback;}catch{return fallback;}};
const savePref=(k,v)=>{try{localStorage.setItem('twin-'+k,v);}catch{}};
let lang=pref('lang','en');if(!['it','en'].includes(lang))lang='en';
let theme=pref('theme','system');
let vault=null,key=null,salt=null,record=null,revision=0,unlocked=false,paid=false,page='today',busy=false,charts=[],activeEpoch=0;
let search='',searchHits=null,scenarioReduction=15,futureText='',patternText='',progressInfo=null,swReady=false,installPrompt=null,hiddenTimer;
let errorMessage='',errorDetail='',caps={mode:'cpu',webgpu:false};
const tr=(it,en)=>lang==='it'?it:en;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>money(n,lang);
const dateText=value=>parseDay(value).toLocaleDateString(lang==='it'?'it-IT':'en-GB',{day:'numeric',month:'short'});
const paths={twin:'<ellipse cx="9" cy="12" rx="5" ry="8" transform="rotate(-18 9 12)"/><ellipse cx="15" cy="12" rx="5" ry="8" transform="rotate(18 15 12)"/>',today:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v4m8-4v4M4 11h16m-10 4h4"/>',ask:'<path d="M21 11a8 8 0 0 1-8 8H7l-4 3v-7a8 8 0 0 1 8-11h2a8 8 0 0 1 8 7Z"/><path d="M8 11h8m-8 4h5"/>',patterns:'<path d="M4 20V10m8 10V4m8 16v-7"/>',futures:'<path d="M12 21v-7m0 0L5 7m7 7 7-7M5 12V7h5m4 0h5v5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1v3l-2 2 2 2v3l3 1 1 3h6l1-3 3-1v-3l2-2-2-2V7l-3-1-1-3Z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',moon:'<path d="M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10Z"/>',mic:'<rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5 11v1a7 7 0 0 0 14 0v-1m-7 8v3m-4 0h8"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',memory:'<rect x="5" y="3" width="15" height="18" rx="2"/><path d="M9 3v18m4-12h3m-3 4h3"/>',letter:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m3 7 9 6 9-6"/>',check:'<path d="m5 12 4 4L19 6"/>',spark:'<path d="m12 3 2 6 6 3-6 2-2 7-2-7-6-2 6-3Z"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.spark}</svg>`;
const brand=(mobile=false)=>`<div class="brand ${mobile?'mobile-brand':''}">${icon('twin')}<span>twin<span style="color:var(--muted)">.</span></span></div>`;
function themeApply(){const dark=theme==='dark'||(theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.lang=lang;document.title=tr('Twin — Il tuo spazio, la tua voce','Twin — Your space, your voice');document.querySelector('meta[name=theme-color]').content=dark?'#141c19':'#f5f5f2';}
const langSelect=()=>`<select aria-label="${tr('Lingua','Language')}" data-change="language"><option value="en" ${lang==='en'?'selected':''}>EN</option><option value="it" ${lang==='it'?'selected':''}>IT</option></select>`;
function progressHTML(){return `<div class="progress-panel" aria-live="polite"><progress ${progressInfo?.progress!=null?`value="${progressInfo.progress}"`:''} max="1" ${!busy?'hidden':''}></progress><p data-progress>${esc(progressInfo?.text||'')}</p>${busy?`<button class="action-link" data-action="cancel">${tr('Interrompi','Cancel')}</button>`:''}</div>`;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),5000);}
function progress(p){progressInfo=p;for(const el of root.querySelectorAll('[data-progress]'))el.textContent=p.text;for(const el of root.querySelectorAll('progress')){el.hidden=false;if(p.progress==null)el.removeAttribute('value');else el.value=p.progress;}}
function friendly(error){
  if(error.message==='AI_WORKER_FAILED'||error.message==='AI_WORKER_MESSAGE_FAILED'||/wasm|WebAssembly|memory|allocation|backend|fetch|network|device lost/i.test(error.message||''))return tr('L’AI locale non è partita. Il diario resta salvato. Riprova con Wi-Fi e spazio libero; se disponibile, prova la modalità CPU.','Local AI could not start. Your diary is still saved. Retry with Wi-Fi and free storage; if available, try CPU mode.');
  if(error.message==='CONFLICT')return tr('Un’altra scheda ha modificato questi dati. Blocca e riapri Twin per caricare la versione aggiornata.','Another tab changed this vault. Lock and reopen Twin to load the latest version.');
  if(error.message==='VAULT_FULL')return tr('Archivio pieno (24 MiB). Esporta un backup e riduci le voci prima di continuare.','Vault full (24 MiB). Export a backup and reduce entries before continuing.');
  if(error.message==='AI_CANCELLED')return tr('Operazione interrotta.','Operation cancelled.');
  if(error.message?.startsWith('LICENSE'))return tr('Codice non valido o verifica non supportata da questo browser.','Invalid code or verification unsupported in this browser.');
  if(error.name==='QuotaExceededError')return tr('Spazio esaurito. Esporta un backup e libera spazio sul dispositivo.','Storage full. Export a backup and free device storage.');
  if(error.name==='OperationError')return tr('Password errata o backup danneggiato.','Wrong password or damaged backup.');
  return tr('Operazione non riuscita. Controlla connessione, spazio e compatibilità del browser. Riprova o usa CPU.','Operation failed. Check connection, storage and browser compatibility. Retry or use CPU.');
}
async function run(fn){
  if(busy)return;busy=true;errorMessage='';errorDetail='';const epoch=activeEpoch;
  root.querySelectorAll('button:not([data-action="cancel"]):not([data-action="lock"]),input,textarea,select').forEach(el=>el.disabled=true);
  root.querySelectorAll('.progress-panel').forEach(el=>{el.querySelector('progress').hidden=false;if(!el.querySelector('[data-action=cancel]')){const b=document.createElement('button');b.type='button';b.className='action-link';b.dataset.action='cancel';b.textContent=tr('Interrompi','Cancel');el.append(b);}});
  try{await fn(epoch);}catch(error){if(epoch===activeEpoch){errorMessage=friendly(error);errorDetail=String(error.message||error).slice(0,1200);toast(errorMessage);}}
  finally{if(epoch===activeEpoch){busy=false;progressInfo=null;render();}}
}
function checkEpoch(epoch){if(epoch!==activeEpoch||!unlocked)throw new Error('AI_CANCELLED');}
async function persist(candidate=vault,epoch=activeEpoch){
  validateVault(candidate);const encrypted=await seal(candidate,key,salt);checkEpoch(epoch);
  const next=await writeRecord(encrypted,revision);checkEpoch(epoch);
  revision=next;record={...encrypted,revision};vault=candidate;
}
async function checkPaid(){paid=false;if(vault?.license){try{await verifyLicense(vault.license);paid=true;}catch{}}}
function demoAllowed(kind){if(paid||vault.usage[kind]<3)return true;page='settings';toast(tr('Limite demo raggiunto. Sblocca Twin con il tuo codice.','Demo limit reached. Unlock Twin with your code.'));render();return false;}
function noAI(){const cached=ai.aiState().cached;toast(cached?tr('Carica i modelli dalla cache in Impostazioni.','Load models from cache in Settings.'):tr('Scarica prima i modelli locali da Impostazioni.','Download the local models in Settings first.'));page='settings';}
function importForm(gate=false){return `<details class="top-gap"><summary class="muted">${tr('Ripristina un backup cifrato','Restore an encrypted backup')}</summary><form data-form="import" class="top-gap"><label>${tr('File JSON Twin','Twin JSON file')}<input type="file" name="backup" accept=".json,application/json" required></label><label>${tr('Password del backup','Backup password')}<input type="password" name="backupPassword" autocomplete="off" required></label><label class="inline-checkbox"><input type="checkbox" required>${tr('Il ripristino sostituisce tutti i dati locali. Ho conservato un backup.','Restoring replaces all local data. I have kept a backup.')}</label><button class="btn secondary" type="submit">${tr('Ripristina','Restore')}</button></form></details>`;}
function gate(){
  const exists=!!record;
  return `<main class="gate"><section class="gate-story">${brand()}<div><div class="eyebrow">${tr('UNO SPAZIO SOLO TUO','A SPACE THAT’S ONLY YOURS')}</div><h1>${tr('Ritrova la tua<br><span class="serif">voce migliore.</span>','Find your<br><span class="serif">better self.</span>')}</h1><p>${tr('Un piccolo diario. Una memoria gentile. Un gemello che impara ad ascoltarti.','A small diary. A thoughtful memory. A twin that learns to listen.')}</p></div><div class="orb" aria-hidden="true"></div><div class="gate-footer" style="color:#b5c6b2">${tr('Sul tuo dispositivo. Al tuo ritmo.','On your device. At your pace.')}</div></section><section class="gate-form"><div class="gate-tools">${langSelect()}<button class="icon-btn" data-action="theme" aria-label="${tr('Cambia tema','Change theme')}">${icon('moon')}</button></div><div class="eyebrow">${exists?tr('BENTORNATO','WELCOME BACK'):tr('COMINCIAMO DA TE','LET’S BEGIN WITH YOU')}</div><h2>${exists?tr('Il tuo spazio ti aspetta.','Your space is waiting.'):tr('Piacere, sono Twin.','Hi, I’m Twin.')}</h2><p class="muted">${exists?tr('La tua password apre i ricordi, solo qui.','Your password unlocks your memories, only here.'):tr('Tre piccoli obiettivi. Un posto per ricordare cosa conta.','Three small goals. A place to remember what matters.')}</p>${errorMessage?`<p role="alert" class="error">${esc(errorMessage)}</p>${errorDetail?`<details><summary>${tr('Dettagli tecnici','Technical details')}</summary><p class="text-content">${esc(errorDetail)}</p></details>`:''}`:''}<form data-form="${exists?'unlock':'onboard'}">${!exists?`<label>${tr('Come ti chiami?','Your name')}<input name="name" maxlength="80" autocomplete="given-name" required></label>`:''}<div class="${!exists?'field-row':''}"><label>${exists?'Password':tr('Password (almeno 12 caratteri)','Password (at least 12 characters)')}<input type="password" name="password" minlength="12" maxlength="256" autocomplete="${exists?'current-password':'new-password'}" required></label>${!exists?`<label>${tr('Ripeti password','Repeat password')}<input type="password" name="confirm" minlength="12" maxlength="256" autocomplete="new-password" required></label>`:''}</div>${!exists?`<fieldset class="stack"><legend>${tr('I tuoi tre obiettivi','Your three goals')}</legend>${[1,2,3].map((n)=>`<input aria-label="${tr('Obiettivo','Goal')} ${n}" name="goal${n}" maxlength="240" placeholder="${[tr('Es. mettere da parte per un viaggio','E.g. save for a trip'),tr('Es. dormire con più regolarità','E.g. sleep more regularly'),tr('Es. avere tempo per me','E.g. make time for myself')][n-1]}" required>`).join('')}</fieldset><label>${tr('Budget mensile per le spese (€)','Monthly spending budget (€)')}<input type="number" name="budget" inputmode="decimal" min="0" max="100000000" step="0.01" required></label>`:''}<button class="btn full" type="submit">${exists?tr('Apri Twin','Open Twin'):tr('Crea il mio spazio','Create my space')}${icon('arrow')}</button></form><div class="gate-footer">${icon('lock')} ${tr('Cifratura AES-256-GCM. La password non è recuperabile. Nessun account e nessun caricamento dei tuoi contenuti. I modelli richiedono un download iniziale (circa 1 GB).','AES-256-GCM encryption. Your password cannot be recovered. No account and no content uploads. Models need an initial download (around 1 GB).')}<br>${tr('Demo: 3 note e 3 richieste AI. Twin completo: 29 € una tantum.','Demo: 3 notes and 3 AI requests. Full Twin: €29 once.')}<br><strong>${tr('Twin è un’AI locale, non una persona. Può sbagliare.','Twin is local AI, not a person. It can make mistakes.')}</strong><br><a href="${lang==='it'?'./privacy-it.html':'./privacy.html'}">Privacy</a> · <a href="${lang==='it'?'./terms-it.html':'./terms.html'}">${tr('Condizioni','Terms')}</a> · <a href="./licenses/THIRD-PARTY.txt">Built with Llama</a></div>${importForm(true)}${progressHTML()}</section></main>`;
}
const navItems=[['today','today',()=>tr('Oggi','Today')],['ask','ask',()=>tr('Chiedi a Twin','Ask Twin')],['patterns','patterns',()=>tr('I tuoi schemi','Patterns')],['futures','futures',()=>tr('Due futuri','Two futures')],['settings','settings',()=>tr('Impostazioni','Settings')]];
function shell(content){return `<div class="shell"><aside class="sidebar">${brand()}<div class="brand-sub">${tr('IL TUO IO MIGLIORE','YOUR BETTER SELF')}</div><nav class="nav" aria-label="${tr('Menu principale','Main menu')}">${navItems.map(([id,i,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${label()}</span></button>`).join('')}</nav><div class="sidebar-bottom"><span class="badge">${icon('lock')}${tr('Privato, per natura','Private by nature')}</span><p>${tr('I tuoi ricordi restano qui.<br>La tua storia appartiene a te.','Your memories stay here.<br>Your story belongs to you.')}</p><button class="btn ghost full" data-page="settings">${paid?tr('Twin completo','Full Twin'):tr('Demo · Scopri Twin completo','Demo · Unlock full Twin')}</button></div></aside><main class="main"><header class="topbar">${brand(true)}<span class="topbar-label">${new Date().toLocaleDateString(lang==='it'?'it-IT':'en-GB',{weekday:'long',day:'numeric',month:'long'})}</span><div class="topbar-actions"><span class="badge"><i class="dot"></i>${swReady?tr('App disponibile offline','App available offline'):tr('Solo sul dispositivo','On-device only')}</span>${langSelect()}<button class="icon-btn" data-action="theme" aria-label="${tr('Cambia tema','Change theme')}">${icon('moon')}</button><button class="icon-btn" data-action="lock" aria-label="${tr('Blocca Twin','Lock Twin')}">${icon('lock')}</button><span class="avatar" aria-hidden="true">${esc(vault.profile.name.slice(0,1).toUpperCase())}</span></div></header><div class="content">${errorMessage?`<div class="note-box warning" role="alert">${esc(errorMessage)}${errorDetail?`<details class="top-gap"><summary>${tr('Dettagli tecnici','Technical details')}</summary><p class="text-content">${esc(errorDetail)}</p></details>`:''}</div>`:''}${content}<div class="footer-mark">${icon('lock')}${tr('La tua vita non è un dato da condividere.','Your life is yours to keep.')} · <a href="${lang==='it'?'./privacy-it.html':'./privacy.html'}">Privacy</a> · <a href="${lang==='it'?'./terms-it.html':'./terms.html'}">${tr('Condizioni','Terms')}</a> · <a href="./licenses/THIRD-PARTY.txt">Built with Llama</a></div></div></main></div>`;}
function heading(eyebrow,title,subtitle){return `<div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>`;}
function today(){
  const s=stats(vault.notes),budget=vault.profile.budget,percent=budget?Math.min(100,s.monthSpend/budget*100):0;
  return `<div class="home-hero"><div><div class="eyebrow">${tr('UN MOMENTO PER TE','A MOMENT FOR YOU')}</div><h1>${tr('Ciao','Hello')}, ${esc(vault.profile.name)}<span class="serif">.</span></h1><p>${tr('Non serve avere tutto chiaro. Partiamo da oggi.','You don’t need every answer. Let’s start with today.')}</p></div><div class="orb" aria-hidden="true"></div></div><div class="grid"><section class="card journal"><div class="row between"><h2>${tr('Com’è andata oggi?','How was today?')}</h2><span class="badge">30 ${tr('secondi','seconds')}</span></div><p class="muted">${tr('Un pensiero basta. Noi teniamo il filo.','One thought is enough. We’ll keep the thread.')}</p><form data-form="note"><label><span class="hidden">${tr('La tua giornata','Your day')}</span><textarea name="text" maxlength="6000" placeholder="${tr('Oggi mi sono sentito… Ho speso per… Sto pensando di…','Today I felt… I spent on… I’m thinking about…')}" required></textarea></label><div class="row between"><input class="label-date" aria-label="${tr('Data della nota','Entry date')}" name="date" type="date" value="${dayKey()}" max="${dayKey()}" required><button class="icon-btn" type="button" data-action="dictate" aria-label="${tr('Dettatura locale','Local dictation')}">${icon('mic')}</button></div><fieldset><legend>${tr('Il tuo umore','Your mood')}</legend><div class="mood">${['☁','◔','◑','◕','☀'].map((face,i)=>`<label><input type="radio" name="mood" value="${i+1}" aria-label="${tr('Umore','Mood')} ${i+1}/5" ${i===2?'checked':''}><span>${face}</span></label>`).join('')}</div></fieldset><div class="field-row"><label>${tr('Spese del giorno (€)','Daily expenses (€)')}<input name="spend" type="number" inputmode="decimal" min="0" max="10000000" step="0.01" value="0" required></label><label>${tr('Ore di sonno','Hours of sleep')}<input name="sleep" type="number" inputmode="decimal" min="0" max="24" step="0.1" value="7" required></label></div><footer><small>${paid?tr('Solo tuo. Sempre.','Always yours.'):tr(`${Math.max(0,3-vault.usage.notes)} note demo rimaste`,`${Math.max(0,3-vault.usage.notes)} demo notes left`)}</small><button class="btn" type="submit">${tr('Conserva il ricordo','Save this memory')}${icon('arrow')}</button></footer></form></section><section class="card"><div class="row between"><h3 style="margin:0">${tr('Questo mese, con calma','This month, at a glance')}</h3>${icon('patterns')}</div><div class="metric-number">${fmt(s.monthSpend)} <small>/ ${fmt(budget)}</small></div><small>${tr('Spese annotate · i giorni mancanti non sono zero','Recorded expenses · missing days are not zero')}</small><div class="budget-track"><span style="width:${percent}%"></span></div><div class="row between"><small>${s.monthDays} ${tr('giorni annotati','recorded days')}</small><small>${budget?fmt(budget-s.monthSpend):'—'} ${tr('residuo','remaining')}</small></div></section><section class="card quote-card"><div class="eyebrow">${tr('RICORDIAMOCI PERCHÉ','REMEMBER OUR WHY')}</div><p class="serif">“${esc(vault.profile.goals[0])}”</p><small>${tr('È una cosa che hai detto di volere. Facciamole spazio.','You said this matters. Let’s make room for it.')}</small><button class="action-link" data-page="ask">${tr('Ne parliamo con Twin','Talk it through with Twin')}${icon('arrow')}</button></section></div><div class="section-label">${tr('PICCOLE TRACCE, UN QUADRO PIÙ GRANDE','SMALL TRACES, A BIGGER PICTURE')}</div><div class="grid"><button class="card" data-page="memories" style="text-align:left"><div class="row between"><div><h3>${tr('La tua memoria','Your memory')}</h3><small>${vault.notes.length} ${tr('ricordi, una sola storia','memories, one story')}</small></div>${icon('memory')}</div></button><button class="card" data-page="letter" style="text-align:left"><div class="row between"><div><h3>${tr('Una lettera da noi','A letter from us')}</h3><small>${weeklyDue(vault.letters)?tr('La lettera di questa settimana ti aspetta','Your weekly letter is waiting'):tr('La tua lettera è pronta','Your letter is ready')}</small></div>${icon('letter')}</div></button></div>${!ai.aiState().ready?`<div class="note-box top-gap">${tr('Il diario è già pronto. Per parlare con Twin, scarica i modelli in Impostazioni. Servono spazio libero e il primo collegamento a Internet.','Your diary is ready. To talk to Twin, download the models in Settings. You’ll need free storage and an initial Internet connection.')} <button class="action-link" data-page="settings">${tr('Prepara Twin','Set up Twin')}${icon('arrow')}</button></div>`:''}`;
}
function sourceList(sources){return !sources?.length?'':`<details class="sources"><summary>${tr('Ricordi forniti a Twin — verifica le fonti','Memories supplied to Twin — check the sources')} (${sources.length})</summary>${sources.map((n,i)=>`<blockquote><strong>[${i+1}] ${esc(dateText(n.date))}</strong><br>${esc(n.text)}</blockquote>`).join('')}</details>`;}
function askPage(){return heading(tr('UNA PAUSA PRIMA DI DECIDERE','A PAUSE BEFORE YOU DECIDE'),tr('Chiedi a <span class="serif">Twin.</span>','Ask <span class="serif">Twin.</span>'),tr('Guardiamo la scelta attraverso ciò che conta per noi.','Let’s see this choice through what matters to us.'))+`<section class="card"><form data-form="ask"><label>${tr('A cosa stai pensando?','What’s on your mind?')}<textarea name="question" rows="3" maxlength="1000" placeholder="${tr('Lo compro? Accetto questa proposta?','Should I buy it? Should I accept this offer?')}" required></textarea></label><div class="suggestions">${[tr('Questa spesa è coerente con i miei obiettivi?','Does this purchase fit our goals?'),tr('Cosa mi aiuta a stare meglio?','What helps me feel better?')].map(q=>`<button type="button" data-suggestion="${esc(q)}">${esc(q)}</button>`).join('')}</div><div class="row between"><small>${paid?tr('AI locale. Può sbagliare: rileggi le fonti.','Local AI can make mistakes. Check its sources.'):tr(`${3-vault.usage.questions} richieste AI demo rimaste`,`${3-vault.usage.questions} demo AI requests left`)}</small><button class="btn" type="submit">${tr('Pensiamoci insieme','Let’s think it through')}${icon('spark')}</button></div></form>${progressHTML()}</section><div class="stack top-gap">${vault.chats.slice().reverse().map(c=>`<article class="card"><div class="chat-bubble">${esc(c.question)}</div><div class="eyebrow">TWIN · ${tr('RISPOSTA GENERATA DA AI LOCALE','GENERATED BY LOCAL AI')}</div><p class="text-content" data-ai-generated="true" data-generator="Twin">${esc(c.answer)}</p>${sourceList(c.sources)}${c.goals?`<div class="sources top-gap"><strong>${tr('Obiettivi forniti a Twin','Goals supplied to Twin')}</strong>${c.goals.map(g=>`<p>“${esc(g)}”</p>`).join('')}</div>`:''}</article>`).join('')}</div>`;}
function patternsPage(){const s=stats(vault.notes);return heading(tr('GUARDARSI, SENZA GIUDICARSI','NOTICE, WITHOUT JUDGEMENT'),tr('I tuoi <span class="serif">schemi.</span>','Your <span class="serif">patterns.</span>'),tr('Piccoli segnali calcolati dai giorni annotati. Le correlazioni non dimostrano cause.','Small signals calculated from recorded days. Correlation does not establish cause.'))+`<div class="stat-grid"><div class="card"><small>${tr('Umore medio','Mean mood')}</small><div class="metric-number">${s.averageMood?.toFixed(1)||'—'}<small> / 5</small></div></div><div class="card"><small>${tr('Sonno medio','Mean sleep')}</small><div class="metric-number">${s.averageSleep?.toFixed(1)||'—'}<small> h</small></div></div><div class="card"><small>${tr('Giorni annotati','Recorded days')}</small><div class="metric-number">${s.observedDays}</div></div></div><div class="grid top-gap"><section class="card"><h2>${tr('Il filo dell’umore','A thread of moods')}</h2><div class="chart-wrap"><canvas id="mood-chart" role="img" aria-label="${tr('Serie di umore nei giorni annotati','Mood over recorded days')}"></canvas></div></section><section class="card"><h2>${tr('Dove vanno le spese','When spending happens')}</h2><p class="muted">${tr('Media per giorno della settimana, solo sui giorni annotati.','Weekday averages across recorded days only.')}</p><div class="chart-wrap"><canvas id="week-chart" role="img" aria-label="${tr('Spesa media per giorno della settimana','Mean spending by weekday')}"></canvas></div></section><section class="card span-2"><h2>${tr('Sonno e spese: c’è un legame?','Sleep and spending: a connection?')}</h2><p>${s.sleepSpendCorrelation===null?tr('Servono almeno 7 giorni annotati e valori variabili per calcolare una correlazione.','At least 7 recorded days and varying values are needed for a correlation.'):`r = ${s.sleepSpendCorrelation.toFixed(2)} · n = ${s.observedDays}`}</p><p class="muted">${tr('Dati descrittivi, senza test di significatività. Campioni piccoli e giorni mancanti possono distorcere il risultato.','Descriptive data, without significance testing. Small samples and missing days can distort the result.')}</p><button class="btn secondary" data-action="explain">${tr('Twin, aiutaci a leggere i dati','Twin, help us read the data')}</button>${progressHTML()}${patternText?`<p class="review-tag">${tr('Spiegazione generata da AI locale','Explanation generated by local AI')}</p><p class="text-content" data-ai-generated="true" data-generator="Twin">${esc(patternText)}</p>`:''}<details class="top-gap"><summary class="muted">${tr('Dati accessibili e metodo','Accessible data and method')}</summary><div class="table-wrap"><table><thead><tr><th>${tr('Data','Date')}</th><th>€</th><th>${tr('Umore','Mood')}</th><th>${tr('Sonno','Sleep')}</th></tr></thead><tbody>${s.days.map(d=>`<tr><td>${esc(d.date)}</td><td>${d.spend.toFixed(2)}</td><td>${d.mood.toFixed(1)}</td><td>${d.sleep.toFixed(1)}</td></tr>`).join('')}</tbody></table></div></details></section></div>`;}
function futuresPage(){const s=stats(vault.notes),p=projection(s,scenarioReduction);return heading(tr('NON UNA PREVISIONE. UNA POSSIBILITÀ.','NOT A PREDICTION. A POSSIBILITY.'),tr('Due <span class="serif">futuri.</span>','Two <span class="serif">futures.</span>'),tr('Una piccola abitudine, vista lungo dodici mesi.','One small habit, seen across twelve months.'))+`<section class="card"><label>${tr('Se riducessimo le spese annotate del','If we reduced recorded spending by')} <strong id="reduction-label">${scenarioReduction}%</strong><input id="reduction" type="range" min="0" max="80" step="5" value="${scenarioReduction}" data-change="reduction"></label><p class="help-line">${tr('Ipotesi: riduzione uniforme della spesa media, non di una categoria riconosciuta. Nessun reddito, interesse o inflazione inclusi.','Assumption: a uniform reduction in mean spending, not an identified category. No income, interest or inflation included.')}</p>${p?`<div class="metric-number">${fmt(p.difference)}</div><p class="muted">${tr('di differenza nelle spese cumulative dopo 12 mesi, sotto queste ipotesi.','difference in cumulative spending after 12 months, under these assumptions.')}</p><div class="chart-wrap"><canvas id="future-chart" role="img" aria-label="${tr('Due scenari di spesa cumulativa a 12 mesi','Two cumulative spending scenarios over 12 months')}"></canvas></div><div class="note-box top-gap">${tr(`Basato su ${s.observedDays} giorni annotati. I giorni non registrati sono sconosciuti. Una settimana può non rappresentare un anno: questo è un esempio aritmetico, non una previsione né un consiglio di investimento.`,`Based on ${s.observedDays} recorded days. Unrecorded days are unknown. One week may not represent a year: this is an arithmetic example, not a forecast or investment advice.`)}</div><button class="btn secondary top-gap" data-action="future-story">${tr('Raccontaci questi due futuri','Tell us about these two futures')}</button>${progressHTML()}${futureText?`<p class="review-tag">${tr('Racconto generato da AI locale','Story generated by local AI')}</p><p class="text-content" data-ai-generated="true" data-generator="Twin">${esc(futureText)}</p>`:''}<details class="top-gap"><summary class="muted">${tr('Valori e formula','Values and formula')}</summary><p class="help-line">${tr('Spesa media dei giorni annotati × 365,2425 ÷ 12 × mesi. Secondo scenario × (1 − riduzione / 100).','Mean spending on recorded days × 365.2425 ÷ 12 × months. Second scenario × (1 − reduction / 100).')}</p><table><thead><tr><th>${tr('Mese','Month')}</th><th>${tr('Continuiamo','Continue')}</th><th>−${scenarioReduction}%</th></tr></thead><tbody>${p.baseline.map((v,i)=>`<tr><td>${i}</td><td>${fmt(v)}</td><td>${fmt(p.changed[i])}</td></tr>`).join('')}</tbody></table></details>`:`<div class="empty">${tr('Annotiamo almeno 7 giorni prima di costruire uno scenario.','Let’s record at least 7 days before creating a scenario.')}</div>`}</section>`;}
function memoriesPage(){const notes=(searchHits||vault.notes.slice().sort((a,b)=>b.date.localeCompare(a.date)));return heading(tr('NULLA DA DIMOSTRARE. QUALCOSA DA RICORDARE.','NOTHING TO PROVE. SOMETHING TO REMEMBER.'),tr('La tua <span class="serif">memoria.</span>','Your <span class="serif">memory.</span>'),tr('Le tue parole, al sicuro. La ricerca usa il significato, non solo le parole.','Your words, kept safe. Search by meaning, beyond keywords.'))+`<section class="card"><form data-form="search"><label>${tr('Cerca un ricordo','Find a memory')}<input name="search" value="${esc(search)}" maxlength="1000" placeholder="${tr('Quando mi sono sentito più sereno?','When did I feel more at ease?')}" required></label><div class="row"><button class="btn secondary" type="submit">${tr('Cerca per significato','Search by meaning')}</button><button class="btn ghost" type="button" data-action="clear-search">${tr('Tutti','All')}</button></div></form>${progressHTML()}${notes.length?notes.map(n=>`<article class="memory"><div class="row between"><span class="eyebrow" style="margin:0">${esc(dateText(n.date))}</span><button class="icon-btn" data-delete-note="${esc(n.id)}" aria-label="${tr('Elimina nota','Delete note')}">${icon('close')}</button></div><p>${esc(n.text)}</p><div class="memory-meta"><span>${fmt(n.spend)}</span><span>${tr('Umore','Mood')} ${n.mood}/5</span><span>${n.sleep} h ${tr('di sonno','of sleep')}</span><span>${n.embedding?tr('Memoria semantica pronta','Semantic memory ready'):tr('Indicizzazione in attesa','Indexing pending')}</span></div></article>`).join(''):`<div class="empty">${tr('Le prime tracce arriveranno con il tuo diario.','Your first memories will arrive with your diary.')}</div>`}</section>`;}
function letterPage(){const due=weeklyDue(vault.letters);return heading(tr('CON LA TUA VOCE MIGLIORE','IN YOUR BETTER VOICE'),tr('Una lettera <span class="serif">da noi.</span>','A letter <span class="serif">from us.</span>'),tr('Ogni domenica, un momento per guardarci con più gentilezza.','Every Sunday, a moment to look at ourselves more kindly.'))+`<section class="card"><p class="muted">${tr('La lettera viene generata sul dispositivo all’apertura di Twin, se i modelli sono pronti. Se l’app è chiusa non può lavorare in sottofondo. In demo, la generazione è manuale e usa una richiesta AI.','The letter is generated on-device when Twin opens, if models are ready. It cannot run while the app is closed. In demo, generation is manual and uses an AI request.')}</p><button class="btn secondary" data-action="letter" ${!due||!vault.notes.length?'disabled':''}>${due?tr('Scrivi la lettera settimanale','Write the weekly letter'):tr('Questa settimana abbiamo già scritto','This week’s letter is ready')}</button>${progressHTML()}${vault.letters.slice().reverse().map(l=>`<article class="memory"><div class="eyebrow">${esc(dateText(l.date))}</div><p class="review-tag">${tr('Lettera generata da AI locale','Letter generated by local AI')}</p><p class="text-content letter" data-ai-generated="true" data-generator="Twin">${esc(l.text)}</p></article>`).join('')}</section>`;}
function settings(){const state=ai.aiState(),pending=vault.notes.filter(n=>!n.embedding).length;return heading(tr('IL TUO SPAZIO, LE TUE REGOLE','YOUR SPACE, YOUR RULES'),tr('Semplicemente, <span class="serif">tuo.</span>','Simply, <span class="serif">yours.</span>'),tr('Nessun account. Nessuna sincronizzazione. Tu conservi la chiave.','No account. No sync. You hold the key.'))+`<div class="grid"><section class="card"><h2>${tr('L’intelligenza, qui.','Intelligence, right here.')}</h2><p class="muted">${tr('I download iniziali contengono modelli pubblici. Note, domande ed embedding vengono elaborati sul dispositivo e salvati cifrati. Nessuna telemetria applicativa.','Initial downloads contain public models. Notes, questions and embeddings are processed on-device and stored encrypted. No application telemetry.')}</p><div class="note-box ${state.mode==='cpu'?'warning':''}">${state.mode==='gpu'?'WebGPU · Llama 3.2 1B':ai.isAppleMobile()?tr('Compatibilità iPhone/iPad: Qwen 2.5 0.5B locale su CPU. Più lento, con meno memoria richiesta.','iPhone/iPad compatibility: local Qwen 2.5 0.5B on CPU. Slower, with lower memory requirements.'):tr('WebGPU/f16 non disponibile o CPU selezionata. Qwen 2.5 0.5B su CPU: sarà più lento.','WebGPU/f16 unavailable or CPU selected. Qwen 2.5 0.5B on CPU: it will be slower.')}</div><p class="help-line">${tr('Circa 1 GB di download per Llama; il fallback Qwen q8 è circa 512 MB, più embedding e runtime. Tieni almeno 2 GB liberi. Dimensioni e memoria effettive variano.','Around 1 GB of downloads for Llama; Qwen q8 is around 512 MB, plus embeddings and runtimes. Keep at least 2 GB free. Actual sizes and memory requirements vary.')}</p><div class="row" style="flex-wrap:wrap"><button class="btn" data-action="load-ai">${icon('download')}${state.cached?tr('Carica modelli dalla cache','Load models from cache'):tr('Scarica modelli locali','Download local models')}</button>${state.mode==='gpu'?`<button class="btn ghost" data-action="cpu">${tr('Usa CPU','Use CPU')}</button>`:''}</div>${ai.isAppleMobile()?`<p class="help-line">${tr('Su iPhone/iPad avvia l’AI da questo pulsante dopo lo sblocco. Il diario resta utilizzabile senza caricare i modelli.','On iPhone/iPad, start AI with this button after unlocking. The diary remains usable without loading models.')}</p>`:''}${progressHTML()}<p class="help-line">${state.ready?tr('Modelli caricati. Esegui un riavvio in modalità aereo per verificare la cache sul tuo dispositivo.','Models loaded. Restart in airplane mode to verify this device’s cache.'):tr('Diario e statistiche disponibili anche senza modelli.','Diary and statistics work without models.')} ${pending?tr(`${pending} note in attesa di embedding.`,`${pending} notes awaiting embeddings.`):''}</p><button class="action-link" data-action="storage">${tr('Controlla spazio e proteggi i dati locali','Check storage and request persistence')}</button><p class="help-line">${tr('Il browser può eliminare dati e cache se manca spazio. Esporta regolarmente un backup. Rimuovere l’app non garantisce la cancellazione dei dati del browser.','The browser may evict data and caches when storage runs low. Export regular backups. Removing the app may not delete browser data.')}</p></section><section class="card"><h2>${paid?tr('Twin è tuo.','Twin is yours.'):tr('Tutta la tua storia.','Your whole story.')}</h2><div class="metric-number">29 € <small>${tr('una tantum','one time')}</small></div><p class="muted">${paid?tr('Codice verificato sul dispositivo. Nessun abbonamento.','Code verified on-device. No subscription.'):tr('La demo include 3 note e 3 richieste AI totali: domande, racconti, spiegazioni o lettere. La ricerca nei ricordi non consuma richieste.','Demo includes 3 notes and 3 AI requests in total: questions, stories, explanations or letters. Memory search does not use requests.')}</p>${!paid?`<form data-form="license"><label>${tr('Hai già acquistato? Inserisci il codice','Already purchased? Enter your code')}<textarea name="code" rows="3" maxlength="4096" spellcheck="false" required placeholder="TWIN1.…"></textarea></label><button class="btn secondary" type="submit">${tr('Sblocca Twin','Unlock Twin')}</button></form>`:`<span class="badge">${icon('check')}${tr('Licenza completa attiva','Full license active')}</span>`}<p class="help-line">${tr('Il codice viene consegnato dal venditore dopo l’acquisto su Shopify. La verifica funziona offline.','Your seller delivers the code after your Shopify purchase. Verification works offline.')}</p></section><section class="card"><h2>${tr('Ciò che conta per noi','What matters to us')}</h2><form data-form="profile"><label>${tr('Nome','Name')}<input name="name" value="${esc(vault.profile.name)}" maxlength="80" required></label>${vault.profile.goals.map((g,i)=>`<label>${tr('Obiettivo','Goal')} ${i+1}<input name="goal${i+1}" value="${esc(g)}" maxlength="240" required></label>`).join('')}<label>${tr('Budget mensile (€)','Monthly budget (€)')}<input name="budget" type="number" min="0" max="100000000" step="0.01" value="${vault.profile.budget}" required></label><button class="btn secondary" type="submit">${tr('Aggiorna','Update')}</button></form></section><section class="card"><h2>${tr('I tuoi dati','Your data')}</h2><div class="stack"><button class="btn secondary" data-action="export">${icon('download')}${tr('Esporta tutto, cifrato','Export everything, encrypted')}</button>${importForm()}<details><summary class="muted">${tr('Cambia password','Change password')}</summary><form data-form="password" class="top-gap"><label>${tr('Password attuale','Current password')}<input name="old" type="password" autocomplete="current-password" required></label><label>${tr('Nuova password (min. 12 caratteri)','New password (min. 12 characters)')}<input name="new" type="password" minlength="12" maxlength="256" autocomplete="new-password" required></label><label>${tr('Ripeti nuova password','Repeat new password')}<input name="confirm" type="password" minlength="12" maxlength="256" autocomplete="new-password" required></label><button class="btn ghost" type="submit">${tr('Cambia password','Change password')}</button></form></details><label>${tr('Aspetto','Appearance')}<select data-change="appearance"><option value="system" ${theme==='system'?'selected':''}>${tr('Automatico','System')}</option><option value="light" ${theme==='light'?'selected':''}>${tr('Chiaro','Light')}</option><option value="dark" ${theme==='dark'?'selected':''}>${tr('Scuro','Dark')}</option></select></label><button class="btn ghost" data-action="install">${tr('Installa Twin','Install Twin')}</button><details><summary class="error">${tr('Cancella tutti i dati Twin','Erase all Twin data')}</summary><form data-form="erase" class="top-gap"><p class="muted">${tr('Elimina dati, licenza e preferenze di questa installazione. Rimuove le cache dei modelli di Twin su questa origine. I backup esportati restano dove li hai salvati.','Deletes this installation’s data, license and preferences. Removes Twin model caches on this origin. Exported backups stay where you saved them.')}</p><label>${tr('Scrivi CANCELLA per confermare','Type DELETE to confirm')}<input name="confirmation" required autocomplete="off"></label><button class="btn danger" type="submit">${tr('Cancella definitivamente','Erase permanently')}</button></form></details></div></section><section class="card span-2"><h3>${tr('Prima di fidarci, capiamo i limiti.','Understand the limits before relying on Twin.')}</h3><p class="muted">${tr('Twin recupera fino a 5 ricordi pertinenti. MiniLM è orientato soprattutto all’inglese: la ricerca in italiano può essere meno precisa. Un modello piccolo può inventare o citare male: verifica sempre numeri e fonti. Non offre consulenza medica, legale o finanziaria professionale. La password protegge i dati a riposo; il dispositivo sbloccato, le estensioni del browser o codice compromesso possono accedere ai contenuti.','Twin retrieves up to 5 relevant memories. MiniLM is primarily English-oriented: Italian search may be less accurate. A small model can invent facts or miscite sources: always check numbers and references. It does not offer professional medical, legal or financial advice. Your password protects data at rest; an unlocked device, browser extensions or compromised code can access content.')}</p><p class="help-line">${tr('La dettatura è disponibile solo con riconoscimento vocale locale garantito dal browser. I server di hosting e dei modelli vedono le normali richieste di download, incluso l’indirizzo IP; non ricevono il tuo diario.','Dictation is available only when the browser guarantees local speech recognition. Hosting and model servers see ordinary download requests, including the IP address; they do not receive your diary.')}</p></section></div>`;}
function render(){themeApply();charts.forEach(c=>c.destroy());charts=[];root.innerHTML=unlocked?shell(({today,ask:askPage,patterns:patternsPage,futures:futuresPage,memories:memoriesPage,letter:letterPage,settings}[page]||today)()):gate();if(unlocked)drawCharts();if(busy)root.querySelectorAll('button:not([data-action="cancel"]):not([data-action="lock"]),input,textarea,select').forEach(el=>el.disabled=true);}
function drawCharts(){
  const s=stats(vault.notes),color=getComputedStyle(document.documentElement).getPropertyValue('--muted').trim(),line=getComputedStyle(document.documentElement).getPropertyValue('--line').trim();
  const options={responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},ticks:{color,maxTicksLimit:7}},y:{grid:{color:line},ticks:{color}}}};
  const draw=(id,type,data,extra={})=>{const el=document.getElementById(id);if(el)charts.push(new Chart(el,{type,data,options:{...options,...extra}}));};
  draw('mood-chart','line',{labels:s.days.map(d=>dateText(d.date)),datasets:[{data:s.days.map(d=>d.mood),borderColor:'#819b77',backgroundColor:'#819b7715',fill:true,tension:.25,pointRadius:3}]},{scales:{...options.scales,y:{...options.scales.y,min:1,max:5,ticks:{stepSize:1,color}}}});
  const weekdays=lang==='it'?['Dom','Lun','Mar','Mer','Gio','Ven','Sab']:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  draw('week-chart','bar',{labels:weekdays,datasets:[{data:s.weekdays.map(d=>d.mean),backgroundColor:'#98ac88',borderRadius:5}]});
  const p=projection(s,scenarioReduction);if(p)draw('future-chart','line',{labels:p.baseline.map((_,i)=>`${i}`),datasets:[{label:tr('Se continuiamo','If we continue'),data:p.baseline,borderColor:'#a7aba1',borderDash:[5,5],pointRadius:0},{label:tr('Se cambiamo','If we change'),data:p.changed,borderColor:'#75916b',backgroundColor:'#75916b10',pointRadius:0,fill:true}]},{plugins:{legend:{display:true,labels:{color,usePointStyle:true,boxWidth:8,font:{size:11}}}},scales:{...options.scales,y:{...options.scales.y,beginAtZero:true,title:{display:true,text:tr('Spese cumulative (€)','Cumulative spending (€)'),color}},x:{...options.scales.x,title:{display:true,text:tr('Mesi','Months'),color}}}});
}
async function indexMissing(epoch){
  const candidate=structuredClone(vault);let changed=false;
  for(const [i,n] of candidate.notes.entries())if(!n.embedding||n.embeddingModel!==EMBEDDING_MODEL){progress({text:tr(`Memoria ${i+1}/${candidate.notes.length}`,`Memory ${i+1}/${candidate.notes.length}`),progress:i/candidate.notes.length});n.embedding=await ai.embed(n.text,progress);checkEpoch(epoch);n.embeddingModel=EMBEDDING_MODEL;changed=true;}
  if(changed)await persist(candidate,epoch);
}
async function prepare(epoch){
  await navigator.storage?.persist?.().catch(()=>false);await ai.loadAI(progress);checkEpoch(epoch);await indexMissing(epoch);savePref('ai-enabled','yes');
  toast(tr('Twin è pronto sul dispositivo.','Twin is ready on your device.'));
  if(paid&&vault.notes.length&&weeklyDue(vault.letters))await writeLetter(epoch);
}
async function answer(question,epoch,{kind='question',scenario=null}={}){
  await indexMissing(epoch);checkEpoch(epoch);
  let memories=[];
  if(vault.notes.length){const embedding=await ai.embed(question,progress);checkEpoch(epoch);memories=retrieve(vault.notes,embedding);}
  progress({text:tr('Twin sta riflettendo sul dispositivo…','Twin is reflecting on-device…'),progress:null});
  const answer=await ai.generate(messages({profile:vault.profile,statistics:stats(vault.notes),memories,question,language:lang,scenario}),progress);checkEpoch(epoch);
  if(typeof answer!=='string'||!answer.trim())throw new Error('EMPTY_AI_RESPONSE');
  return {answer:answer.slice(0,12000),sources:memories.map(({id,date,text})=>({id,date,text}))};
}
async function writeLetter(epoch){
  const due=weeklyDue(vault.letters);if(!due||!vault.notes.length)return;
  const start=parseDay(due);start.setDate(start.getDate()-6);const startKey=dayKey(start);
  const weekNotes=vault.notes.filter(n=>n.date>=startKey&&n.date<=due);
  const question=tr('Scrivi una breve lettera da parte della nostra versione migliore. Ricorda un obiettivo reale. Distingui cosa sappiamo da cosa non sappiamo.','Write a brief letter from our better self. Recall an actual goal. Separate what we know from what we don’t know.');
  if(!weekNotes.length){toast(tr('Non ci sono ancora note nella settimana conclusa domenica.','There are no entries for the week ending on Sunday yet.'));return;}
  const recent=weekNotes.slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(-5);
  progress({text:tr('Una lettera da noi…','A letter from us…'),progress:null});
  const text=await ai.generate(messages({profile:vault.profile,statistics:stats(vault.notes,parseDay(due)),memories:recent,question:question+` (Period: ${startKey} to ${due}. Memories are from this period; statistics are historical up to ${due}.)`,language:lang}),progress);checkEpoch(epoch);
  if(!text?.trim())throw new Error('EMPTY_AI_RESPONSE');
  const candidate=structuredClone(vault);candidate.letters.push({id:crypto.randomUUID(),date:due,aiGenerated:true,text:text.slice(0,12000)});candidate.usage.questions++;await persist(candidate,epoch);
}
function lock(){ai.stop();activeEpoch++;busy=false;vault=null;key=null;salt=null;unlocked=false;paid=false;futureText='';patternText='';search='';searchHits=null;errorMessage='';errorDetail='';progressInfo=null;clearTimeout(hiddenTimer);render();}
function download(content,name){const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function onSubmit(event){
  const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();if(busy)return;
  const f=new FormData(form),type=form.dataset.form;
  const str=k=>String(f.get(k)||'').trim();
  if(type==='onboard'){
    if(f.get('password')!==f.get('confirm'))return toast(tr('Le password non coincidono.','Passwords do not match.'));
    return run(async(epoch)=>{const nextSalt=newSalt(),nextKey=await deriveKey(f.get('password'),nextSalt);const profile={name:str('name'),goals:[1,2,3].map(i=>str('goal'+i)),budget:Number(f.get('budget'))};const candidate=validateVault(createVault(profile));const encrypted=await seal(candidate,nextKey,nextSalt);if(epoch!==activeEpoch)return;const next=await writeRecord(encrypted,0);if(epoch!==activeEpoch){record=await readRecord();return;}salt=nextSalt;key=nextKey;vault=candidate;revision=next;record={...encrypted,revision:next};unlocked=true;paid=false;page='today';});
  }
  if(type==='unlock')return run(async(epoch)=>{record=await readRecord();const nextKey=await deriveKey(f.get('password'),from64(record.salt));const data=validateVault(await unseal(record,nextKey));if(epoch!==activeEpoch)return;key=nextKey;salt=from64(record.salt);vault=data;revision=record.revision;unlocked=true;lastActivity=Date.now();page='today';await checkPaid();if(pref('ai-enabled','')==='yes'&&!ai.isAppleMobile())await prepare(epoch);});
  if(type==='import')return run(async(epoch)=>{
    const file=f.get('backup');if(!file||file.size>50_000_000)throw new Error('INVALID_BACKUP');
    const imported=validateEnvelope(JSON.parse(await file.text()));const newSalt=from64(imported.salt),newKey=await deriveKey(f.get('backupPassword'),newSalt);const data=validateVault(await unseal(imported,newKey));
    if(epoch!==activeEpoch)return;
    const latest=await readRecord();const expected=unlocked?revision:(latest?.revision||0);
    const encrypted=await seal(data,newKey,newSalt);if(epoch!==activeEpoch)return;const newRevision=await writeRecord(encrypted,expected);if(epoch!==activeEpoch)return;
    ai.stop();key=newKey;salt=newSalt;vault=data;revision=newRevision;record={...encrypted,revision};unlocked=true;await checkPaid();page='today';futureText='';patternText='';searchHits=null;toast(tr('Backup ripristinato.','Backup restored.'));
  });
  if(!unlocked)return;
  if(type==='note'){
    if(!demoAllowed('notes'))return;
    return run(async(epoch)=>{
      const note={id:crypto.randomUUID(),date:str('date'),text:str('text'),spend:Number(f.get('spend')),mood:Number(f.get('mood')),sleep:Number(f.get('sleep')),embedding:null,embeddingModel:EMBEDDING_MODEL};
      if(!note.text||note.date>dayKey())throw new Error('INVALID_NOTE');
      if(ai.aiState().ready){try{note.embedding=await ai.embed(note.text,progress);}catch(error){if(error.message==='AI_CANCELLED')throw error;toast(tr('Nota salvata; indicizzazione da riprovare.','Entry saved; indexing can be retried.'));}}
      checkEpoch(epoch);const candidate=structuredClone(vault);candidate.notes.push(note);candidate.usage.notes++;validateVault(candidate);await persist(candidate,epoch);searchHits=null;futureText='';patternText='';toast(tr('Ricordo conservato.','Memory saved.'));
    });
  }
  if(type==='ask'){
    if(!demoAllowed('questions'))return;if(!ai.aiState().ready){noAI();return render();}
    return run(async(epoch)=>{const question=str('question');if(!question)return;const result=await answer(question,epoch);const candidate=structuredClone(vault);candidate.chats.push({id:crypto.randomUUID(),date:dayKey(),question,...result,aiGenerated:true,goals:[...vault.profile.goals]});candidate.usage.questions++;await persist(candidate,epoch);});
  }
  if(type==='search'){
    if(!ai.aiState().ready){noAI();return render();}
    return run(async(epoch)=>{search=str('search');await indexMissing(epoch);const e=await ai.embed(search,progress);checkEpoch(epoch);searchHits=retrieve(vault.notes,e);});
  }
  if(type==='profile')return run(async(epoch)=>{const candidate=structuredClone(vault);candidate.profile={name:str('name'),goals:[1,2,3].map(i=>str('goal'+i)),budget:Number(f.get('budget'))};validateVault(candidate);await persist(candidate,epoch);futureText='';patternText='';toast(tr('Obiettivi aggiornati.','Goals updated.'));});
  if(type==='license')return run(async(epoch)=>{await verifyLicense(str('code'));checkEpoch(epoch);const candidate=structuredClone(vault);candidate.license=str('code');await persist(candidate,epoch);paid=true;toast(tr('Twin completo attivato.','Full Twin unlocked.'));});
  if(type==='password'){
    if(f.get('new')!==f.get('confirm'))return toast(tr('Le password non coincidono.','Passwords do not match.'));
    return run(async(epoch)=>{await unseal(record,await deriveKey(f.get('old'),salt));const nextSalt=newSalt(),nextKey=await deriveKey(f.get('new'),nextSalt);const encrypted=await seal(vault,nextKey,nextSalt);checkEpoch(epoch);const next=await writeRecord(encrypted,revision);checkEpoch(epoch);key=nextKey;salt=nextSalt;revision=next;record={...encrypted,revision};toast(tr('Password aggiornata. I backup precedenti mantengono la vecchia password.','Password updated. Older backups keep their old password.'));});
  }
  if(type==='erase'){
    if(str('confirmation')!==tr('CANCELLA','DELETE'))return toast(tr('Scrivi CANCELLA per confermare.','Type DELETE to confirm.'));
    return run(async()=>{
      ai.stop();await eraseRecord();
      const warnings=[];
      if('caches'in window)for(const name of await caches.keys())if(/^(webllm|tvmjs|transformers-cache)/i.test(name))await caches.delete(name).catch(()=>warnings.push(name));
      if(indexedDB.databases)for(const db of await indexedDB.databases())if(/^(webllm|tvmjs)/i.test(db.name))await new Promise(resolve=>{const request=indexedDB.deleteDatabase(db.name);request.onsuccess=resolve;request.onerror=()=>{warnings.push(db.name);resolve();};request.onblocked=()=>{warnings.push(db.name);resolve();};});
      for(const k of ['ai-enabled','theme','lang']){try{localStorage.removeItem('twin-'+k);}catch{}}
      record=null;revision=0;lock();toast(warnings.length?tr('Diario eliminato. Chiudi le altre schede Twin e cancella i dati del sito per rimuovere ogni cache.','Diary erased. Close other Twin tabs and clear site data to remove every cache.'):tr('Dati Twin eliminati.','Twin data erased.'));
    });
  }
}
root.addEventListener('submit',onSubmit);
root.addEventListener('invalid',()=>toast(tr('Controlla i campi obbligatori, la password (almeno 12 caratteri) e i valori numerici.','Check required fields, password length (at least 12 characters), and numeric values.')),true);
root.addEventListener('click',event=>{
  const btn=event.target.closest('button');if(!btn)return;
  if(btn.dataset.action==='lock'){lock();return;}
  if(btn.dataset.action==='cancel'){ai.stop();activeEpoch++;busy=false;progressInfo=null;toast(tr('Operazione interrotta.','Operation cancelled.'));render();return;}
  if(busy)return;
  if(btn.dataset.page){page=btn.dataset.page;errorMessage='';render();window.scrollTo({top:0});return;}
  if(btn.dataset.suggestion){const input=root.querySelector('[name=question]');input.value=btn.dataset.suggestion;input.focus();return;}
  if(btn.dataset.deleteNote){if(!confirm(tr('Eliminare questo ricordo? Il contatore demo non si azzera.','Delete this memory? The demo counter will not reset.')))return;return run(async(epoch)=>{const candidate=structuredClone(vault);candidate.notes=candidate.notes.filter(n=>n.id!==btn.dataset.deleteNote);await persist(candidate,epoch);searchHits=null;futureText='';patternText='';});}
  const action=btn.dataset.action;
  if(action==='theme'){theme=document.documentElement.dataset.theme==='dark'?'light':'dark';savePref('theme',theme);render();}
  if(action==='load-ai')run(prepare);
  if(action==='cpu'){ai.useCPU();savePref('ai-enabled','');render();}
  if(action==='clear-search'){search='';searchHits=null;render();}
  if(action==='export')download(JSON.stringify({...record,revision:undefined},null,2),`Twin-backup-${dayKey()}.json`);
  if(action==='storage')run(async()=>{const persisted=await navigator.storage?.persist?.();const estimate=await navigator.storage?.estimate?.();toast(tr(`Spazio usato: ${Math.round((estimate?.usage||0)/1e6)} MB. Persistenza ${persisted?'accordata':'non garantita'}.`,`Storage used: ${Math.round((estimate?.usage||0)/1e6)} MB. Persistence ${persisted?'granted':'not guaranteed'}.`));});
  if(action==='install'){if(installPrompt){installPrompt.prompt();installPrompt=null;}else toast(tr('Su iPhone: Safari → Condividi → Aggiungi alla schermata Home. Su Android/desktop: menu del browser → Installa app.','On iPhone: Safari → Share → Add to Home Screen. On Android/desktop: browser menu → Install app.'));}
  if(action==='dictate')dictate();
  if(['explain','future-story','letter'].includes(action)){
    if(!demoAllowed('questions'))return;if(!ai.aiState().ready){noAI();return render();}
    return run(async(epoch)=>{
      if(action==='letter'){await writeLetter(epoch);return;}
      const p=action==='future-story'?projection(stats(vault.notes),scenarioReduction):null;
      if(action==='future-story'&&!p)return;
      const q=action==='explain'?tr('Spiega brevemente i nostri schemi calcolati. Non dedurre cause dalle correlazioni.','Briefly explain our calculated patterns. Do not infer causes from correlations.'):tr('Racconta i due scenari a 12 mesi usando solo i valori forniti. Spiega che non sono previsioni.','Describe the two 12-month scenarios using only provided values. Explain that they are not forecasts.');
      const result=await answer(q,epoch,{scenario:p});const candidate=structuredClone(vault);candidate.usage.questions++;await persist(candidate,epoch);if(action==='explain')patternText=result.answer;else futureText=result.answer;
    });
  }
});
root.addEventListener('change',event=>{
  if(busy)return;const type=event.target.dataset.change;
  if(type==='language'){lang=event.target.value;savePref('lang',lang);render();}
  if(type==='appearance'){theme=event.target.value;savePref('theme',theme);render();}
  if(type==='reduction'){scenarioReduction=Number(event.target.value);futureText='';render();}
});
root.addEventListener('input',event=>{if(event.target.id==='reduction')document.getElementById('reduction-label').textContent=event.target.value+'%';});
async function dictate(){
  const Speech=window.SpeechRecognition;
  if(!Speech||!('processLocally'in Speech.prototype))return toast(tr('Dettatura locale non disponibile. Puoi scrivere la nota.','Local dictation is unavailable. You can type your entry.'));
  const recognition=new Speech();recognition.processLocally=true;recognition.lang=lang==='it'?'it-IT':'en-US';recognition.continuous=false;recognition.interimResults=false;let ended=false;
  const epoch=activeEpoch;
  try{
    if(Speech.available){const status=await Speech.available({langs:[recognition.lang],processLocally:true});if(status!=='available'){toast(tr('Installa il pacchetto vocale locale nelle impostazioni del browser, poi riprova.','Install the browser’s local speech language pack, then retry.'));return;}}
    recognition.onresult=event=>{if(epoch!==activeEpoch||!unlocked)return;const field=root.querySelector('[name=text]');if(field)field.value=(field.value+' '+event.results[0][0].transcript).trim().slice(0,6000);};
    recognition.onerror=()=>toast(tr('Dettatura locale non riuscita.','Local dictation failed.'));
    recognition.onend=()=>{ended=true;};recognition.start();toast(tr('Ti ascolto sul dispositivo…','Listening on-device…'));
    const stopOnLock=()=>{if(!unlocked||epoch!==activeEpoch||document.hidden){recognition.abort();clearInterval(timer);}else if(ended)clearInterval(timer);};const timer=setInterval(stopOnLock,500);
  }catch{toast(tr('Il browser non consente la dettatura locale.','The browser could not start local dictation.'));}
}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
document.addEventListener('visibilitychange',()=>{clearTimeout(hiddenTimer);if(document.hidden&&unlocked)hiddenTimer=setTimeout(lock,5*60_000);});
let lastActivity=Date.now();for(const ev of ['pointerdown','keydown'])window.addEventListener(ev,()=>{lastActivity=Date.now();},{passive:true});setInterval(()=>{if(unlocked&&!busy&&Date.now()-lastActivity>10*60_000)lock();},30000);
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if(theme==='system')render();});
window.addEventListener('offline',()=>toast(tr('Sei offline. Usiamo ciò che è già sul dispositivo.','You’re offline. Using what is already on your device.')));
async function boot(){
  try{if(!isSecureContext||!crypto.subtle)throw new Error('HTTPS_REQUIRED');record=await readRecord();revision=record?.revision||0;}catch(error){errorMessage=tr('Servono HTTPS (o localhost), Web Crypto e IndexedDB. La navigazione privata può limitare lo spazio.','HTTPS (or localhost), Web Crypto and IndexedDB are required. Private browsing may limit storage.');}
  render();
  ai.capabilities().then(result=>{caps=result;if(unlocked&&page==='settings'&&!busy)render();});
  if('serviceWorker'in navigator&&import.meta.env.PROD){try{const reg=await navigator.serviceWorker.register(new URL(import.meta.env.BASE_URL+'sw.js',location.href),{scope:import.meta.env.BASE_URL});await navigator.serviceWorker.ready;swReady=true;if(unlocked&&!busy)render();reg.addEventListener('updatefound',()=>toast(tr('Aggiornamento in preparazione. Chiudi tutte le schede Twin per applicarlo dopo il download.','Update preparing. Close all Twin tabs to apply it after download.')));}catch{toast(tr('Cache offline non disponibile. Il diario resta locale.','Offline cache unavailable. Your diary remains local.'));}}
}
